using Acme.Data;
using Microsoft.EntityFrameworkCore;

namespace Acme.Catalog;

public sealed class ProductQueries(ShopDbContext db)
{
    public Task<List<Product>> ListLatestAsync(int page, CancellationToken ct)
    {
        return db.Products
            .AsNoTracking()
            .Include(p => p.Images)
            .Include(p => p.Reviews)
            .OrderByDescending(p => p.UpdatedAt)
            .Skip(page * 20)
            .Take(20)
            .ToListAsync(ct);
    }
}
